    pat = (os.getenv("DEVIN_PAT") or "").strip()
    api_key = (os.getenv("DEVIN_API_KEY") or "").strip()
    token = pat or api_key
    if not token:
        raise ValueError("Missing DEVIN_PAT or DEVIN_API_KEY in environment or .env")
