    },
    "saas-metrics-board": {
        "beat_type": "TRACTION",
        "confidence": 0.95,
        "max_chars": {
            "title": 48,
            "labels": 120,
            "values": 80,
            "trend": 24,
            "accentColor": 32,
        },
    },
    "brand-statement": {
