        "overlays": overlays,
        "subtitles": "master.srt",
    }
    edl_path = variant_dir / "edl.json"
    preview = variant_dir / "preview.mp4"
    reuse_preview = (
        resume
        and preview.exists()
        and edl_path.exists()
        and _read_json(edl_path) == preview_edl
    )
