from __future__ import annotations

import json
import os
import time
from collections.abc import Callable
from dataclasses import dataclass
from typing import Any

import requests


@dataclass(frozen=True)
class DevinCallResult:
    output: dict[str, Any]
    session_id: str
    url: str


SessionCreatedCallback = Callable[[str, str], None]
_CACHED_ORG: tuple[str, str] | None = None
DEVIN_PROMPT_LIMIT_CHARS = 30_000
DEVIN_PROMPT_BUDGET_CHARS = 28_000


@dataclass(frozen=True)
class _DevinTransport:
    token: str
    version: str
    session_base_url: str


def get_devin_token() -> str:
    """Return the active Devin API token (from DEVIN_PAT or DEVIN_API_KEY)."""
    pat = (os.getenv("DEVIN_PAT") or "").strip()
    api_key = (os.getenv("DEVIN_API_KEY") or "").strip()
    token = pat or api_key
    if not token:
        raise ValueError("Missing DEVIN_PAT or DEVIN_API_KEY in environment or .env")
    return token


def get_devin_org_id(token: str) -> str | None:
    """Retrieve organization ID for Devin v3 API."""
    global _CACHED_ORG
    explicit_org = os.getenv("DEVIN_ORG_ID")
    if explicit_org and explicit_org.strip():
        return explicit_org.strip()

    cached_org = _CACHED_ORG
    if cached_org and token == cached_org[0]:
        return cached_org[1]

    headers = {"Authorization": f"Bearer {token}", "Content-Type": "application/json"}
    try:
        response = requests.get("https://api.devin.ai/v3/self", headers=headers, timeout=10)
        if response.status_code == 200:
            data = response.json()
            org_id = (
                data.get("org_id") or data.get("organization_id")
                if isinstance(data, dict)
                else None
            )
            if org_id:
                discovered_org_id = str(org_id)
                _CACHED_ORG = (token, discovered_org_id)
                return discovered_org_id
    except (requests.RequestException, ValueError):
        pass
    return None


def _redact_token(value: str, token: str) -> str:
    """Keep Devin diagnostics useful without ever reflecting credentials."""
    return value.replace(token, "[redacted]") if token else value


def _redact_configured_tokens(value: str) -> str:
    for token in (
        (os.getenv("DEVIN_PAT") or "").strip(),
        (os.getenv("DEVIN_API_KEY") or "").strip(),
    ):
        value = _redact_token(value, token)
    return value


def _is_legacy_api_key(token: str) -> bool:
    return token.startswith(("apk_", "apk_user_"))


def _v1_transport(token: str) -> _DevinTransport:
    base_url = os.getenv("DEVIN_API_URL", "https://api.devin.ai/v1").rstrip("/")
    return _DevinTransport(
        token=token,
        version="v1",
        session_base_url=f"{base_url}/sessions",
    )


def _resolve_transport() -> _DevinTransport:
    pat = (os.getenv("DEVIN_PAT") or "").strip()
    api_key = (os.getenv("DEVIN_API_KEY") or "").strip()
    v3_token = pat or (api_key if api_key.startswith("cog_") else "")

    if not v3_token:
        if not api_key:
            raise ValueError("Missing DEVIN_PAT or DEVIN_API_KEY in environment or .env")
        return _v1_transport(api_key)

    org_id = get_devin_org_id(v3_token)
    if org_id:
        return _DevinTransport(
            token=v3_token,
            version="v3",
            session_base_url=(
                f"https://api.devin.ai/v3/organizations/{org_id}/sessions"
            ),
        )

    # A PAT/cog_ credential is a v3 credential and must never be sent to v1.
    # A separately configured legacy API key is the only safe v1 fallback.
    if pat and _is_legacy_api_key(api_key):
        return _v1_transport(api_key)

    raise RuntimeError(
        "Could not resolve a Devin v3 organization via DEVIN_ORG_ID or /v3/self. "
        "Set DEVIN_ORG_ID, or configure a separate legacy DEVIN_API_KEY "
        "starting with apk_ or apk_user_ for v1 fallback."
    )


def _headers(token: str) -> dict[str, str]:
    return {
        "Authorization": f"Bearer {token}",
        "Content-Type": "application/json",
    }


def _finished_result(
    role_id: str,
    current: dict[str, Any],
    session_id: str,
    session_url: str,
) -> DevinCallResult:
    output = current.get("structured_output")
    if not isinstance(output, dict):
        raise ValueError(f"Devin role {role_id} returned no structured output")
    return DevinCallResult(output=output, session_id=session_id, url=session_url)


def serialize_prompt(prompt: str, context: dict[str, Any]) -> str:
    """Build the exact prompt string counted by Devin's request limit."""
    return (
        f"{prompt}\n\nINPUT JSON:\n"
        f"{json.dumps(context, ensure_ascii=False, separators=(',', ':'))}"
    )


def call(
    role_id: str,
    prompt: str,
    context: dict[str, Any],
    schema: dict[str, Any],
    attempt: int = 0,
    on_session_created: SessionCreatedCallback | None = None,
) -> DevinCallResult:
    """Run one structured Devin session (v3 with v1 fallback) and return its output and identity."""
    serialized_prompt = serialize_prompt(prompt, context)
    if len(serialized_prompt) >= DEVIN_PROMPT_LIMIT_CHARS:
        raise ValueError(
            f"Devin role {role_id} prompt has {len(serialized_prompt)} characters; "
            f"the limit is <{DEVIN_PROMPT_LIMIT_CHARS}"
        )
    transport = _resolve_transport()
    headers = _headers(transport.token)
    run_number = context.get("run_number", 0)
    payload: dict[str, Any] = {
        "prompt": serialized_prompt,
        "structured_output_schema": schema,
        "tags": [f"run-{run_number}", role_id],
        "title": f"Palantum {role_id} · run {run_number}",
        "max_acu_limit": int(os.getenv(f"PALANTUM_{role_id}_MAX_ACU", "5")),
    }
    snapshot_id = os.getenv("DEVIN_SNAPSHOT_ID")
    if snapshot_id and transport.version == "v1":
        payload["snapshot_id"] = snapshot_id
    if transport.version == "v3":
        payload["structured_output_required"] = True

    created = requests.post(
        transport.session_base_url,
        headers=headers,
        json=payload,
        timeout=60,
    )
    try:
        created.raise_for_status()
    except requests.HTTPError as exc:
        detail = _redact_configured_tokens(created.text.strip())[:2000]
        raise RuntimeError(
            f"Devin role {role_id} session creation failed "
            f"({created.status_code}): {detail or 'no response body'}"
        ) from exc
    session = created.json()
    session_id = str(session["session_id"])
    session_url = str(session.get("url") or f"https://app.devin.ai/sessions/{session_id}")
    if on_session_created is not None:
        on_session_created(session_id, session_url)

    timeout_s = float(os.getenv("PALANTUM_DEVIN_TIMEOUT_S", "600"))
    poll_interval_s = float(os.getenv("PALANTUM_DEVIN_POLL_INTERVAL_S", "10"))
    deadline = time.monotonic() + timeout_s
    while time.monotonic() < deadline:
        response = requests.get(
            f"{transport.session_base_url}/{session_id}",
            headers=headers,
            timeout=30,
        )
        response.raise_for_status()
        current = response.json()
        if not isinstance(current, dict):
            raise ValueError(f"Devin role {role_id} returned an invalid session payload")

        if transport.version == "v3":
            v3_status = str(current.get("status") or "")
            status_detail = str(current.get("status_detail") or "")
            output = current.get("structured_output")
            if v3_status == "running" and status_detail == "finished":
                return _finished_result(role_id, current, session_id, session_url)
            if v3_status == "exit" and isinstance(output, dict):
                return DevinCallResult(
                    output=output,
                    session_id=session_id,
                    url=session_url,
                )
            if v3_status in {"exit", "error", "suspended"}:
                redacted_status_detail = _redact_configured_tokens(status_detail)
                detail = _redact_configured_tokens(str(current))
                raise RuntimeError(
                    f"Devin role {role_id} ended {v3_status} "
                    f"({redacted_status_detail or 'no status detail'}): {detail}"
                )
        else:
            v1_status = current.get("status_enum") or current.get("status")
            output = current.get("structured_output")
            if v1_status in {"finished", "blocked"} and isinstance(output, dict):
                return DevinCallResult(
                    output=output,
                    session_id=session_id,
                    url=session_url,
                )
            if v1_status == "finished":
                return _finished_result(role_id, current, session_id, session_url)
            if v1_status in {"blocked", "expired", "stopped"}:
                detail = _redact_configured_tokens(str(current))
                raise RuntimeError(
                    f"Devin role {role_id} ended {v1_status}: {detail}"
                )
        time.sleep(poll_interval_s)

    terminated = requests.delete(
        f"{transport.session_base_url}/{session_id}",
        headers=headers,
        timeout=30,
    )
    terminated.raise_for_status()
    if attempt == 0:
        return call(
            role_id,
            prompt,
            context,
            schema,
            attempt=1,
            on_session_created=on_session_created,
        )
    raise TimeoutError(f"Devin role {role_id} exceeded {timeout_s:.0f}s")
        takes.append(take)
    return {
        "takes": takes,
        "beat_candidates": [
            {"beat": beat, "candidates": values}
            for beat, values in candidates.items()
        ],
    }


def _compact_a4_context(
    base_context: dict[str, Any], *, beat: str | None, candidate_limit: int
) -> dict[str, Any]:
    reduced_beats, candidates = _a4_candidates(
        base_context, beat=beat, candidate_limit=candidate_limit
    )
    director = base_context.get("director", {})
    supervisor = base_context.get("script_supervisor", {})
    word_index = base_context.get("word_index", {})
    context: dict[str, Any] = {
        key: base_context[key]
        for key in ("run_number", "_session_state_path", "_manifest_generation", "schema")
        if key in base_context
    }
    context.update(
        {
            "director": {
                "beats": reduced_beats,
                "beat_order": [str(item["id"]) for item in reduced_beats],
                "order_reason": (
                    str(director.get("order_reason", ""))
                    if isinstance(director, dict)
                    else ""
                ),
            },
            "script_supervisor": _a4_supervisor_context(
                supervisor if isinstance(supervisor, dict) else {}, candidates
            ),
            "takes_packed": _a4_packed_candidates(candidates),
            "word_index": _a4_word_index(
                word_index if isinstance(word_index, dict) else {}, candidates
            ),
        }
    )
    return context


def _budgeted_a4_context(
    base_context: dict[str, Any],
    prompt: str,
    *,
    beat: str | None = None,
    extra: dict[str, Any] | None = None,
) -> dict[str, Any]:
    last_size = 0
    for candidate_limit in range(_A4_MAX_CANDIDATES_PER_BEAT, 0, -1):
        context = _compact_a4_context(
            base_context, beat=beat, candidate_limit=candidate_limit
        )
        if extra:
            context.update(extra)
        last_size = len(serialize_prompt(prompt, context))
        if last_size <= DEVIN_PROMPT_BUDGET_CHARS:
            return context
    scope = beat or "all beats"
    raise ValueError(
        f"A4 prompt for {scope} has {last_size} characters after compaction; "
        f"the safe budget is {DEVIN_PROMPT_BUDGET_CHARS}"
    )


def _chunk_groups(ranges: list[dict[str, Any]]) -> list[dict[str, Any]]:
    groups: list[dict[str, Any]] = []
    for item in ranges:
        beat = str(item["beat"])
        if groups and groups[-1]["beat"] == beat:
            groups[-1]["seed_ranges"].append(item)
            continue
        slug = re.sub(r"[^a-z0-9]+", "-", beat.lower()).strip("-") or "segment"
        groups.append(
            {
                "id": f"chunk-{len(groups):02d}-{slug}",
                "order": len(groups),
                "beat": beat,
                "seed_ranges": [item],
            }
        )
    return groups


def _copy_chunk_transcripts(
    edit_dir: Path, variant_dir: Path, ranges: list[dict[str, Any]]
) -> None:
    target = variant_dir / "transcripts"
    target.mkdir(parents=True, exist_ok=True)
    for source in {str(item["source"]) for item in ranges}:
        transcript = edit_dir / "transcripts" / f"{source}.json"
        if transcript.exists():
            shutil.copy2(transcript, target / transcript.name)


def _validate_chunk_ranges(
    chunk: dict[str, Any], ranges: list[dict[str, Any]], source_map: dict[str, str]
) -> list[dict[str, Any]]:
    if not ranges:
        raise ValueError(f"{chunk['id']} variant returned no ranges")
    validated: list[dict[str, Any]] = []
    for item in ranges:
        if str(item.get("beat")) != str(chunk["beat"]):
            raise ValueError(f"{chunk['id']} variant returned a different beat")
        source = str(item.get("source"))
        if source not in source_map:
            raise ValueError(f"{chunk['id']} variant selected unknown source {source}")
        start = float(item["start"])
        end = float(item["end"])
        if start < 0 or end <= start:
            raise ValueError(f"{chunk['id']} variant returned an invalid range")
        validated.append(dict(item))
    return validated


def _build_chunk_variant(
    edit_dir: Path,
    state: dict[str, Any],
    chunk: dict[str, Any],
    variant: dict[str, Any],
    source_map: dict[str, str],
    base_context: dict[str, Any],
    motion_source: Path | None,
    approved_catalog: dict[str, Any] | None,
    target_size: tuple[int, int],
    *,
    resume: bool,
) -> dict[str, Any]:
    variant_id = str(variant["id"])
    variant_dir = edit_dir / "chunks" / str(chunk["id"]) / variant_id
    prompt = _prompt("A4")
    context = _budgeted_a4_context(
        base_context,
        prompt,
        beat=str(chunk["beat"]),
        extra={
        "_session_key": f"{chunk['id']}.{variant_id}",
        "chunk": chunk,
        "variant": {
            "id": variant_id,
            "name": variant["name"],
            "direction": variant["direction"],
        },
        },
    )
    decision = _cached_role(
        edit_dir,
        f"A4-{chunk['id']}-{variant_id}",
        "A4",
        prompt,
        context,
        resume=resume,
    )
    ranges = _validate_chunk_ranges(chunk, decision["ranges"], source_map)
    overlays: list[dict[str, Any]] = []
    if bool(variant["motion"]):
        if motion_source is None:
            raise RuntimeError("the motion variant requires a configured template source")
        overlays = _graphics_overlays(
            variant_dir,
            state,
            ranges,
            motion_source,
            target_size,
            resume=resume,
            approved_catalog=approved_catalog,
            required_overlays=1,
        )
        if len(overlays) != 1:
            raise RuntimeError(
                f"the motion variant requires exactly one overlay, got {len(overlays)}"
            )
    _copy_chunk_transcripts(edit_dir, variant_dir, ranges)
    preview_edl = {
        "sources": source_map,
        "ranges": ranges,
        "grade": state["brand"].get("grade", "neutral_punch"),
        "overlays": overlays,
        "subtitles": "master.srt",
    }
    edl_path = variant_dir / "edl.json"
    preview = variant_dir / "preview.mp4"
    reuse_preview = (
        resume
        and preview.exists()
        and edl_path.exists()
        and _read_json(edl_path) == preview_edl
    )
    _write_json(edl_path, preview_edl)
    if not reuse_preview:
        render(variant_dir, preview, preview=True)
    measured = probe(preview)
    duration = sum(float(item["end"]) - float(item["start"]) for item in ranges)
    final_overlays = []
    for overlay in overlays:
        item = dict(overlay)
        item["file"] = str((variant_dir / str(overlay["file"])).resolve())
        final_overlays.append(item)
    return {
        "id": variant_id,
        "label": variant["label"],
        "name": variant["name"],
        "strategy": variant["direction"],
        "status": "ready",
        "duration_s": measured.duration_s,
        "expected_duration_s": duration,
        "probe": _file_free_probe_context(measured),
        "ranges": ranges,
        "overlays": final_overlays,
        "preview": preview.relative_to(edit_dir).as_posix(),
        "notes": str(decision.get("notes", "")),
    }


def _variant_supervisor_context(
    chunk: dict[str, Any], variants: list[dict[str, Any]], base_context: dict[str, Any]
) -> dict[str, Any]:
    """Build a compact, file-free comparison payload for the optional A5 review."""
    comparable = []
    for variant in variants:
        comparable.append(
            {
                "id": str(variant["id"]),
                "name": str(variant.get("name", "")),
                "strategy": str(variant.get("strategy", "")),
                "duration_s": float(variant.get("duration_s", 0)),
                "expected_duration_s": float(variant.get("expected_duration_s", 0)),
                "probe": (
                    dict(variant["probe"])
                    if isinstance(variant.get("probe"), dict)
                    else {}
                ),
                "ranges": [
                    {
                        "source": str(item.get("source", "")),
                        "start": float(item.get("start", 0)),
                        "end": float(item.get("end", 0)),
                        "quote": str(item.get("quote", "")),
                        "reason": str(item.get("reason", "")),
                    }
                    for item in variant.get("ranges", [])
                    if isinstance(item, dict)
                ],
                "overlays": [
                    {
                        "template_id": str(item.get("template_id", "")),
                        "beat": str(item.get("beat", "")),
                        "duration": float(item.get("duration", 0)),
                        "reason": str(item.get("reason", "")),
                    }
                    for item in variant.get("overlays", [])
                    if isinstance(item, dict)
                ],
                "notes": str(variant.get("notes", "")),
            }
        )
    return {
        "run_number": base_context["run_number"],
        "_session_state_path": base_context["_session_state_path"],
        "_session_key": ".".join(
            filter(
                None,
                (
                    str(base_context.get("_manifest_generation", "")),
                    str(chunk["id"]),
                    "recommendation",
                ),
            )
        ),
        "chunk": {
            "id": str(chunk["id"]),
            "beat": str(chunk["beat"]),
            "variants": comparable,
        },
    }


def _recommend_chunk_variant(
    edit_dir: Path,
    chunk: dict[str, Any],
    variants: list[dict[str, Any]],
    base_context: dict[str, Any],
    *,
    resume: bool,
) -> dict[str, Any]:
    """Ask A5 for a preference without making review depend on agent availability."""
    try:
        generation = str(base_context.get("_manifest_generation", ""))
        cache_key = "-".join(filter(None, ("A5", generation, str(chunk["id"]))))
        recommendation = _cached_role(
            edit_dir,
            cache_key,
            "A5",
            _prompt("A5"),
            _variant_supervisor_context(chunk, variants, base_context),
            resume=resume,
        )
        variant_id = str(recommendation["variant_id"])
        if variant_id not in {str(item["id"]) for item in variants}:
            raise ValueError(f"A5 selected unknown variant {variant_id}")
        return {
            "status": "ready",
            "variant_id": variant_id,
            "reason": str(recommendation["reason"]),
        }
    except Exception:
        return {
            "status": "unavailable",
            "variant_id": None,
            "reason": "Die KI-Empfehlung ist derzeit nicht verfügbar.",
        }


def _chunk_base_context(
    edit_dir: Path, state: dict[str, Any], *, manifest_generation: str = ""
) -> dict[str, Any]:
    supervisor_path = edit_dir / "script-supervisor.json"
    director_path = edit_dir / "director.json"
    director = (
        _read_json(director_path)
        if director_path.exists()
        else {
            "beats": state["beats"],
            "beat_order": [beat["id"] for beat in state["beats"]],
        }
    )
    return {
        "run_number": int(state["meta"]["iteration"]),
        "_session_state_path": str(edit_dir / "sessions.json"),
        "_manifest_generation": manifest_generation,
        "schema": _schema(),
        "director": director,
        "script_supervisor": _read_json(supervisor_path) if supervisor_path.exists() else {},
        "takes_packed": (edit_dir / "takes_packed.md").read_text(encoding="utf-8"),
        "word_index": _read_json(edit_dir / "word_index.json"),
    }


def build_chunk_variants(
    edit_dir: Path,
    sources: list[Path],
    template_source: Path | None = None,
    *,
    resume: bool = False,
) -> dict[str, Any]:
    """Create two independently agent-edited previews for every semantic chunk."""
    schema = _schema()
    state = load(edit_dir, schema)
    if not sources:
        raise RuntimeError("no source videos available for chunking")
    generation = uuid.uuid4().hex
    base_context = _chunk_base_context(
        edit_dir, state, manifest_generation=generation
    )
    a4_prompt = _prompt("A4")
    chunk_plan = _cached_role(
        edit_dir,
        "A4-chunk-plan",
        "A4",
        a4_prompt,
        _budgeted_a4_context(base_context, a4_prompt),
        resume=resume,
    )
    chunks = _chunk_groups(chunk_plan["ranges"])
    if not chunks:
        raise RuntimeError("A4 produced no semantic chunks")
    source_map = {source.stem: str(source.resolve()) for source in sources}
    first_source = probe(sources[0])
    target_size = (1080, 1920) if first_source.height > first_source.width else (1920, 1080)
    motion_source = _motion_source(template_source, state)
    if motion_source is None:
        raise RuntimeError(
            "PALANTUM_TEMPLATE_SOURCE fehlt; Variante B benötigt genau eine "
            "validierte Motion Graphic."
        )
    catalog_path = edit_dir / "scene-catalog.json"
    approved_catalog = (
        _read_json(catalog_path) if motion_source is not None and catalog_path.exists() else None
    )
    manifest: dict[str, Any] = {
        "version": 1,
        "generation_id": generation,
        "status": "building",
        "recommendations_status": "pending",
        "sources": source_map,
        "chunks": [
            {
                "id": chunk["id"],
                "order": chunk["order"],
                "beat": chunk["beat"],
                "selected": None,
                "variants": [],
            }
            for chunk in chunks
        ],
    }
    _write_json(edit_dir / "chunks.json", manifest)
    jobs: dict[tuple[str, str], Any] = {}
    with ThreadPoolExecutor(max_workers=min(4, len(chunks) * 2)) as executor:
        for chunk in chunks:
            for variant in _CHUNK_VARIANTS:
                jobs[(str(chunk["id"]), str(variant["id"]))] = executor.submit(
                    _build_chunk_variant,
                    edit_dir,
                    state,
                    chunk,
                    variant,
                    source_map,
                    base_context,
                    motion_source,
                    approved_catalog,
                    target_size,
                    resume=resume,
                )
        for manifest_chunk in manifest["chunks"]:
            manifest_chunk["variants"] = [
                jobs[(str(manifest_chunk["id"]), str(variant["id"]))].result()
                for variant in _CHUNK_VARIANTS
            ]
    manifest["status"] = "review"
    _write_json(edit_dir / "chunks.json", manifest)
    return manifest


def recommend_chunk_variants(
    edit_dir: Path, manifest: dict[str, Any], *, resume: bool = False
) -> dict[str, dict[str, Any]]:
    """Compute optional A5 recommendations without mutating the chunk manifest."""
    chunks = [item for item in manifest.get("chunks", []) if isinstance(item, dict)]
    if not chunks:
        return {}
    generation = str(manifest.get("generation_id", ""))
    state = load(edit_dir, _schema())
    base_context = _chunk_base_context(
        edit_dir, state, manifest_generation=generation
    )
    with ThreadPoolExecutor(max_workers=min(4, len(chunks))) as executor:
