    $('toolbar').hidden = false;
    renderChunkReview(data.chunks || [], data.selection_complete ?? null);
    return !state.pollingRecommendations;
  }
  if (data.phase === 'done' && data.video_url) {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    stopJobActivityPolling();
    $('progress').hidden = true;
    $('chunk-review').hidden = true;
    $('output').hidden = false;
    $('toolbar').hidden = true;
    $('player').src = data.video_url;
    $('export-video').href = data.video_url;
    $('export-folder').href = data.export_url || '#';
