function showAgentActivity(copy) {
  const activity = $('job-agent-activity');
  if (!copy) {
    activity.hidden = true;
    activity.dataset.live = 'false';
    $('job-agent-activity-copy').textContent = '';
    return;
  }
  $('job-agent-activity-copy').textContent = copy;
  activity.dataset.live = 'true';
  activity.hidden = false;
}

function renderAgentActivity(sessions = []) {
  const running = (Array.isArray(sessions) ? sessions : [])
    .find(item => String(item?.status || '').toLowerCase() === 'running');
  if (running) {
    showAgentActivity(agentActivityCopy(running.role));
    return;
  }
  const canvasActivity = [...state.activeCanvasAgents.values()].at(-1);
  showAgentActivity(canvasActivity || '');
}

function beginCanvasAgentActivity(requestId, copy) {
  state.activeCanvasAgents.set(requestId, copy);
  const statusCard = $('job-status-card');
  if (statusCard.hidden || ['error', 'success'].includes(statusCard.dataset.tone)) {
    showJobStatus({
      tone: 'active',
      title: 'Agent analysiert deinen Text',
      detail: 'Der aktuelle Inhalt wird geprüft. Du kannst währenddessen weiterschreiben.',
      eta: 'wenige Sekunden',
      progress: 35,
    });
  }
  renderAgentActivity();
}

function endCanvasAgentActivity(requestId) {
  state.activeCanvasAgents.delete(requestId);
  renderAgentActivity();
  if (!state.activeCanvasAgents.size && !state.uploading && !state.pollingRecommendations && !state.finalizing) {
    hideJobStatus();
  }
}

function showContextHint({ kind = 'context', kicker, title, detail }) {
  const card = $('context-hint-card');
  card.dataset.kind = kind;
  $('context-hint-kicker').textContent = kicker;
  $('context-hint-title').textContent = title;
  $('context-hint-detail').textContent = detail;
  card.hidden = false;
}

function updateContextHint() {
  const recommendation = state.activeRecommendations.find(item => {
    const key = AGENT_META[item.agent]?.key;
    return !key || !state.dismissed[key];
  });
  if (recommendation) {
    const role = recommendation.role || AGENT_META[recommendation.agent]?.role || 'Agent';
    showContextHint({
      kind: 'suggestion',
      kicker: `${recommendation.agent} · ${role}`,
      title: 'Verbesserungsvorschlag',
      detail: recommendation.message || recommendation.ghost_text,
    });
    return;
  }
  const text = $('prompt').value.trim();
  if (text.length > 0 && text.length < 12) {
    showContextHint({
      kind: 'context',
      kicker: 'Kontexthinweis',
      title: 'Mehr Kontext benötigt',
      detail: 'Ergänze Zielgruppe, Problem oder gewünschtes Ergebnis, damit die Agenten sinnvoll starten können.',
    });
    return;
  }
  $('context-hint-card').hidden = true;
}

async function pollJobActivity() {
  if (MOCK) return;
  state.jobActivityPolling = true;
  try {
    const response = await fetch('/api/activity');
    if (response.ok) {
      const data = await response.json();
      renderAgentActivity(data.sessions || []);
    }
  } catch (_) {}
  const keepPolling = state.uploading || state.pollingRecommendations || state.finalizing;
  if (keepPolling) {
    state.jobActivityPollTimer = setTimeout(pollJobActivity, 1200);
  } else {
    state.jobActivityPollTimer = null;
    state.jobActivityPolling = false;
  }
}

function startJobActivityPolling() {
  if (MOCK || state.jobActivityPolling || state.jobActivityPollTimer) return;
  pollJobActivity();
}

function stopJobActivityPolling() {
  clearTimeout(state.jobActivityPollTimer);
  state.jobActivityPollTimer = null;
  state.jobActivityPolling = false;
  renderAgentActivity();
}

