  $('context-hint-kicker').textContent = kicker;
  $('context-hint-title').textContent = title;
  $('context-hint-detail').textContent = detail;
  card.hidden = false;
}

function updateContextHint() {
  const recommendation = state.activeRecommendations.find(item => {
    const key = AGENT_META[item.agent]?.key;
    return !key || !state.dismissed[key];
  });
  if (recommendation) {
    const role = recommendation.role || AGENT_META[recommendation.agent]?.role || 'Agent';
    showContextHint({
      kind: 'suggestion',
      detail: 'Der Auftrag wurde gestoppt. Die genaue Ursache steht im Arbeitsbereich.',
      eta: 'Gestoppt',
      progress: 100,
    });
    return;
  }

  if (phase === 'working') {
    if (!['running', 'finalizing'].includes(reportedStatus)) {
      hideJobStatus();
      setProgressValue(0);
      return;
    }
    const status = reportedStatus;
    const presentation = {
      running: {
        tone: 'active',
        title: 'Video wird erstellt',
        detail: 'Material wird analysiert, geschnitten und als Varianten gerendert.',
        eta: 'ca. 4–8 Min.',
        progress: 58,
      },
      finalizing: {
        tone: 'active',
        title: 'Finales Video wird gerendert',
        detail: 'Die ausgewählten Varianten werden zu einem Video zusammengesetzt.',
        eta: 'ca. 1–3 Min.',
        progress: 88,
      },
    }[status];
    showJobStatus(presentation);
    return;
  }

  if (phase === 'review') {
    if (data.recommendations_status === 'pending') {
      showJobStatus({
        tone: 'active',
        title: 'Varianten sind gerendert',
        detail: 'Die KI-Empfehlungen für die Auswahl werden noch geprüft.',
        eta: 'ca. 1–2 Min.',
        progress: 94,
      });
    } else {
      showJobStatus({
        tone: 'success',
        title: 'Varianten sind bereit',
        detail: 'Du kannst jetzt die Schnittvarianten vergleichen und auswählen.',
        eta: 'Abgeschlossen',
        progress: 100,
        autoHide: 7000,
      });
    }
    return;
  }

  if (phase === 'done' && data.video_url) {
    showJobStatus({
      tone: 'success',
      title: 'Video ist fertig',
      detail: 'Das finale Video kann jetzt angesehen oder exportiert werden.',
  }
