}

function renderBeats(beats = []) {
  $('beats').innerHTML = beats.map(b => `<span class="beat" data-status="${b.status}">${b.id}</span>`).join('');
}

function validChunkRecommendation(chunk) {
  const recommendation = chunk?.recommendation;
  if (!recommendation || !recommendation.variant_id) return null;
  const status = String(recommendation.status || 'ready').toLowerCase();
  if (['failed', 'error', 'unavailable', 'pending'].includes(status)) return null;
  const variant = (chunk.variants || []).find(item => item.id === recommendation.variant_id);
  return variant ? recommendation : null;
}

function chunkVideoUrl(chunkId, variant) {
  return variant.video_url || `/api/chunks/${encodeURIComponent(chunkId)}/variants/${encodeURIComponent(variant.id)}/video`;
}

function renderChunkReview(chunks = [], selectionComplete = null) {
  state.chunks = Array.isArray(chunks) ? chunks : [];
  const list = $('chunk-list');
  list.innerHTML = '';

  state.chunks.forEach((chunk, index) => {
    const section = document.createElement('article');
    section.className = 'chunk';
    showJobStatus({
      tone: 'error',
      title: 'Finaler Render fehlgeschlagen',
      detail: 'Der Auftrag konnte nicht gestartet werden.',
      eta: 'Gestoppt',
      progress: 100,
    });
    $('compose-error').textContent = error.message;
    $('compose-error').hidden = false;
  }
}

function applyServerState(data) {
  hydrateCanvas(data.canvas || state.canvas);
  renderBeats(data.coverage?.beats || []);
  renderJobStatus(data);
  if (data.phase==='error') {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    stopJobActivityPolling();
    $('progress').hidden = true;
    $('output').hidden = true;
    $('toolbar').hidden = false;
    $('compose-error').textContent = data.error || 'Die Videoverarbeitung ist fehlgeschlagen.';
    $('compose-error').hidden = false;
    return true;
  }
  if (data.phase === 'review') {
    state.uploading = false;
    state.recommendationsStatus = data.recommendations_status || 'complete';
    state.pollingRecommendations = data.recommendations_status === 'pending';
    state.finalizing = false;
    if (state.pollingRecommendations) startJobActivityPolling();
    else stopJobActivityPolling();
    $('progress').hidden = true;
    $('output').hidden = true;
    $('chunk-review').hidden = false;
    $('toolbar').hidden = false;
    renderChunkReview(data.chunks || [], data.selection_complete ?? null);
    return !state.pollingRecommendations;
  }
  if (data.phase === 'done' && data.video_url) {
    state.uploading = false;
    state.pollingRecommendations = false;
    state.finalizing = false;
    stopJobActivityPolling();
    $('progress').hidden = true;
    $('chunk-review').hidden = true;
    $('output').hidden = false;
    $('toolbar').hidden = true;
    $('player').src = data.video_url;
    $('export-video').href = data.video_url;
