  }
  if (data.phase === 'working') {
    state.uploading = true;
    state.pollingRecommendations = false;
    startJobActivityPolling();
    const jobStarted = ['running', 'finalizing'].includes(String(data.job_status || '').toLowerCase());
    $('progress').hidden = !jobStarted;
    $('chunk-review').hidden = jobStarted || !data.selection_complete;
